def insert(node, data):

  if node is None:

    return TreeNode(data)

  else:

    if data < node.data:

      node.left = insert(node.left, data)

    elif data > node.data:

      node.right = insert(node.right, data)

  return node



# Inserting new value into the BST

insert(root, 10)
